INSERT INTO `${itemTable}` (
    title, `${authorCol}`, `${isbnCol}`, category_id, stock, status, cover_url
) VALUES (
    #{title}, #{author}, #{isbn}, #{categoryId}, #{stock}, #{status}, #{coverUrl}
)

mapper.select:
SELECT id, title, cover_url FROM `${itemTable}`
WHERE title LIKE #{prefix}
AND deleted_at IS NULL
ORDER BY id DESC
LIMIT #{limit}
